func:
// Connect to the broker with the password from deploy/.env. Nothing secret is
// stored in the flow file, so the flow can live in Git (ADR-0016).
// The Last Will marks this runtime offline if it disappears (ADR-0007).
const runtime = env.get("OFM_RUNTIME_NAME");
msg.action = "connect";
msg.broker = {
    broker: "mosquitto",
    port: 1883,
    clientid: "ofm-" + runtime,
    username: "ofm_runtime",
    password: env.get("OFM_MQTT_RUNTIME_PASSWORD"),
    will: {
        topic: "ofm/_system/runtime/" + runtime,
        payload: JSON.stringify({ state: "offline" }),
        qos: 1,
        retain: true
    }
};
return msg;

// Ask the database for every property this runtime acquires (ADR-0001):
// at start-up, and whenever the model changes (from the listener below).
msg.params = [env.get("OFM_RUNTIME_NAME")];
msg.trigger = msg.trigger === "notify" ? "notify" : "startup";
node.status({ fill: "blue", shape: "dot", text: "loading model" });
return msg;

// Build the in-memory model (ADR-0001) and swap it in as one object, so the
// value path never sees a half-built model and never queries the database.
// Each property's _meta topic (unit, limits, description; schemas/meta) is
// published at start-up and republished when it changes. On a reload, value
// and _meta topics and source status topics that no longer exist are cleared
// from the broker (ADR-0004), and each source gets a signature, so that
// acquisition reconnects only the sources whose connection or addresses changed.
// After every load from the database the rows are also saved to disk (step
// 2.6), so that after a restart the runtime can start from this copy while
// the database cannot be reached (trigger "disk", from "saved model copy").
// Machines with state rules or a heartbeat property (step 3a.3) are gathered
// into model.machines: each rule arrives on the row of the property it tests.
// A machine that no longer has state rules gets its .../state topic cleared.
// Output 1: platform and topic messages. Output 2: sources for acquisition.
// Output 3: after a start-up load from the database only, starts the clean-up
// of stale retained topics (a saved copy may be out of date, so it never does).
// Output 4: after the first load (database or saved copy), starts the
// reconciliation of machine states (ADR-0006 decision 5).
// Output 5: after every load, "refresh" for "work orders" (line topics may
// have changed).
const runtime = env.get("OFM_RUNTIME_NAME");
const trigger = ["notify", "disk"].includes(msg.trigger) ? msg.trigger : "startup";
const savedAt = trigger === "disk" ? msg.savedAt : null;
const previous = global.get("ofm_model");
const rows = Array.isArray(msg.payload) ? msg.payload : [];
const byKey = {}, byProperty = {}, byTopic = {}, sources = {}, metas = {}, machines = {};

function metaOf(r) {                                  // schemas/meta.schema.json
    const m = { propertyId: r.property_id, datatype: r.datatype };
    if (r.unit) m.unit = r.unit;
    m.displayName = String(r.display_name).slice(0, 1024);
    if (r.description) m.description = String(r.description).slice(0, 1024);
    for (const [key, col] of [["low", "low"], ["high", "high"], ["alarmLow", "alarm_low"], ["alarmHigh", "alarm_high"]]) {
        if (r[col] !== null && r[col] !== undefined) m[key] = Number(r[col]);
    }
    m.maxPublishIntervalMs = Number(r.max_publish_interval_ms) || 60000;
    return m;
}

for (const r of rows) {
    const p = {
        propertyId: r.property_id,
        machineId: r.machine_id,
        topic: r.topic,
        datatype: r.datatype,
        unit: r.unit,
        low: r.low,
        high: r.high,
        historised: r.is_historised,
        factor: r.scale_factor === null ? 1 : Number(r.scale_factor),
        offset: r.scale_offset === null ? 0 : Number(r.scale_offset),
        deadband: Number(r.deadband) || 0,                                  // ADR-0007
        maxIntervalMs: Number(r.max_publish_interval_ms) || 60000,
        source: r.cache_key ? r.source_name : null,
        role: r.role || null,
        counter: ["count_in", "count_good", "count_reject"].includes(r.role)    // ADR-0026
    };
    byProperty[p.propertyId] = p;
    byTopic[p.topic] = p;
    metas[p.topic] = metaOf(r);
    if (r.cache_key) {
        byKey[r.cache_key] = p;     // "source|address", e.g. "opcplc|nsu=...;s=SpikeData"
        if (!sources[r.source_name]) {
            sources[r.source_name] = {
                name: r.source_name, protocol: r.protocol, endpoint: r.endpoint,
                settings: r.source_settings || {}, items: []
            };
        }
        sources[r.source_name].items.push({ address: r.address, datatype: r.datatype });
    }
    // Machine states (ADR-0006) and frozen-data detection (ADR-0025).
    const rules = Array.isArray(r.state_rules) ? r.state_rules : [];
    if ((rules.length || r.role === "heartbeat") && r.machine_topic) {
        const m = machines[r.machine_id] || (machines[r.machine_id] =
            { id: r.machine_id, topic: r.machine_topic, rules: [], heartbeat: null, sources: [] });
        if (rules.length) p.stateInput = true;            // "normalise" asks for an evaluation
        for (const rule of rules) {
            m.rules.push({ priority: Number(rule.priority), propertyId: p.propertyId, operator: rule.operator,
                           value: String(rule.value), state: rule.state, datatype: p.datatype });
        }
        if (r.role === "heartbeat") m.heartbeat = { propertyId: p.propertyId, timeoutMs: Number(r.heartbeat_timeout_ms) || 5000 };
        if (p.source && !m.sources.includes(p.source)) m.sources.push(p.source);
    }
}
for (const m of Object.values(machines)) m.rules.sort((a, b) => a.priority - b.priority);

// Protocols the acquisition nodes below can read (ADR-0017, ADR-0018).
const SUPPORTED = ["opcua", "s7", "ethernetip"];
for (const s of Object.values(sources)) {
    if (!SUPPORTED.includes(s.protocol)) node.warn("source " + s.name + ": protocol " + s.protocol + " is not supported yet");
}

const sourceList = Object.values(sources);
for (const s of sourceList) s.signature = JSON.stringify([s.protocol, s.endpoint, s.settings, s.items]);

const loadedAt = Date.now();
const metaText = {};
for (const t of Object.keys(metas)) metaText[t] = JSON.stringify(metas[t]);
global.set("ofm_model", { loadedAt, trigger, savedAt, byKey, byProperty, byTopic, metaText, machines, sourceNames: Object.keys(sources) });
global.set("ofm_unmapped", {});
if (trigger !== "disk") saveCopy();
const when = new Date(loadedAt).toTimeString().slice(0, 8);
node.status(trigger === "disk"
    ? { fill: "yellow", shape: "dot", text: rows.length + " properties from the saved copy - database unreachable, " + when }
    : { fill: "green", shape: "dot", text: rows.length + " properties, " + sourceList.length + " source(s), " + trigger + " " + when });

const cacheStatus = { ts: loadedAt, trigger, rows: rows.length, unmapped: 0 };
if (savedAt) cacheStatus.savedAt = savedAt;
const out = [{ topic: "ofm/_system/cache/" + runtime, payload: cacheStatus, retain: true, qos: 1 }];
// _meta: all at start-up, afterwards only those that changed.
for (const t of Object.keys(metas)) {
    if (previous && previous.metaText && previous.metaText[t] === metaText[t]) continue;
    out.push({ topic: t + "/_meta", payload: metas[t], retain: true, qos: 1 });
}
// An empty retained message deletes a topic from the broker (schemas/README.md).
if (previous) {
    for (const t of Object.keys(previous.byTopic)) {
        if (byTopic[t]) continue;
        out.push({ topic: t, payload: "", retain: true, qos: 1 });
        out.push({ topic: t + "/_meta", payload: "", retain: true, qos: 1 });
    }
    for (const name of previous.sourceNames || []) {
        if (!sources[name]) out.push({ topic: "ofm/_system/sources/" + name, payload: "", retain: true, qos: 1 });
    }
    const stateTopics = new Set(Object.values(machines).filter(m => m.rules.length).map(m => m.topic + "/state"));
    for (const m of Object.values(previous.machines || {})) {
        if (m.rules.length && !stateTopics.has(m.topic + "/state")) out.push({ topic: m.topic + "/state", payload: "", retain: true, qos: 1 });
    }
}
const first = !context.get("loaded");
context.set("loaded", true);
return [out, { payload: sourceList }, trigger === "startup" ? { payload: "clean-up" } : null,
        first ? { payload: "reconcile", trigger } : null, { topic: "refresh" }];

// The copy: {format, runtime, savedAt, rows}, written to a temporary file,
// flushed to the disk and then renamed, so a power cut never leaves half a file.
function saveCopy() {
    const fs = global.get("fs"), path = global.get("path");
    if (!fs || !path) return;
    try {
        const dir = env.get("OFM_MODEL_COPY_DIR") || "/data/model";
        const file = path.join(dir, runtime + ".json");
        fs.mkdirSync(dir, { recursive: true });
        const fd = fs.openSync(file + ".tmp", "w");
        try {
            fs.writeSync(fd, JSON.stringify({ format: 1, runtime, savedAt: loadedAt, rows }));
            fs.fsyncSync(fd);
        } finally {
            fs.closeSync(fd);
        }
        fs.renameSync(file + ".tmp", file);
    } catch (e) {
        node.warn("could not save the model copy: " + e.message +
                  " - values still flow, but after a restart the runtime will need the database to start");
    }
}

// Start-up clean-up (ADR-0004, step 2.2). Clears retained OFM value and _meta
// topics that the model no longer has - for example a property renamed or
// retired while this runtime was not running. (While it runs, every model
// reload clears such topics at once.) Reads the retained messages under each
// enterprise of the model for WINDOW_MS and clears a topic only if
//  - it has the shape of a property topic (6 or 7 levels, or that plus /_meta)
//    and is not a reserved line-level topic (workorder, kpi, spc, foodsafety),
//  - its payload is an OFM live value {v, ts, q, tss} or an OFM _meta,
//  - and no property of ANY runtime has that topic now; for a machine state
//    topic .../{machine}/state (step 3a.3): no machine with state rules has it.
// Anything else on the broker is left alone.
const pg = global.get("pg");
const mqtt = global.get("mqtt");
const WINDOW_MS = 3000;
const RESERVED = ["workorder", "kpi", "spc", "foodsafety"];
if (!pg || !mqtt) {
    node.error("the pg or mqtt library is not available (see nodered/settings.js)");
    return null;
}
const runtime = env.get("OFM_RUNTIME_NAME");
node.status({ fill: "blue", shape: "dot", text: "checking the broker" });

let current, enterprises;
const db = new pg.Client({
    host: "timescaledb", port: 5432, database: "ofm",
    user: env.get("OFM_RUNTIME_DB_USER"), password: env.get("OFM_RUNTIME_DB_PASSWORD"),
    application_name: "ofm-runtime-cleanup", connectionTimeoutMillis: 5000
});
try {
    await db.connect();
    current = new Set((await db.query("SELECT topic FROM config.vw_runtime_model")).rows.map(r => r.topic));
    for (const r of (await db.query("SELECT DISTINCT machine_topic || '/state' AS topic FROM config.vw_runtime_model WHERE state_rules IS NOT NULL")).rows) {
        current.add(r.topic);
    }
    enterprises = (await db.query("SELECT DISTINCT name FROM config.enterprise")).rows.map(r => r.name);
} catch (e) {
    node.status({ fill: "yellow", shape: "ring", text: "skipped: " + e.message });
    return null;
} finally {
    db.end().catch(() => { /* already closed */ });
}
if (enterprises.length === 0) { node.status({}); return null; }

function isValue(p) {
    return p !== null && typeof p === "object" && "v" in p && Number.isFinite(p.ts) &&
        ["good", "uncertain", "bad"].includes(p.q) && ["device", "gateway"].includes(p.tss) &&
        Object.keys(p).every(k => ["v", "ts", "q", "tss"].includes(k));
}
function isMeta(p) {
    return p !== null && typeof p === "object" && Number.isInteger(p.propertyId) && typeof p.datatype === "string";
}

const stale = [];
function check(topic, buf, packet) {
    if (!packet.retain || buf.length === 0) return;          // only stored (retained) messages
    const levels = topic.split("/");
    const isMetaTopic = levels[levels.length - 1] === "_meta";
    const base = isMetaTopic ? levels.slice(0, -1) : levels;
    if (base.length < 6 || base.length > 7) return;
    if (RESERVED.includes(base[4])) return;
    if (base[base.length - 1] === "state" && (isMetaTopic || base.length !== 6)) return;   // only .../{machine}/state
    if (current.has(base.join("/"))) return;
    let p;
    try { p = JSON.parse(buf.toString()); } catch (e) { return; }
    if (isMetaTopic ? isMeta(p) : isValue(p)) stale.push(topic);
}

const client = mqtt.connect("mqtt://mosquitto:1883", {
    username: "ofm_runtime", password: env.get("OFM_MQTT_RUNTIME_PASSWORD"),
    clientId: "ofm-" + runtime + "-cleanup", clean: true, connectTimeout: 5000, reconnectPeriod: 0
});
const ok = await new Promise(resolve => {
    client.on("error", e => { node.status({ fill: "yellow", shape: "ring", text: "skipped: " + e.message }); resolve(false); });
    client.on("message", check);
    client.on("connect", () => {
        client.subscribe(enterprises.map(e => e + "/#"), { qos: 0 }, err => {
            if (err) { resolve(false); return; }
            setTimeout(() => resolve(true), WINDOW_MS);
        });
    });
});
if (ok) {
    client.removeAllListeners("message");
    for (const topic of stale) {
        await new Promise(r => client.publish(topic, "", { retain: true, qos: 1 }, () => r()));
    }
    if (stale.length) node.warn("start-up clean-up: cleared " + stale.length + " stale topic(s), e.g. " + stale.slice(0, 5).join(", "));
    node.status({ fill: "green", shape: "dot", text: "cleared " + stale.length + " stale topic(s)" });
}
client.end(true);
return null;

// Model change listener (ADR-0001, step 2.1). Keeps one database connection
// that LISTENs on "model_changed"; triggers on every configuration table
// notify it when the model is edited (migration 009). Notifications arriving
// within DEBOUNCE_MS are combined into one reload, because one edit in
// Mathesar can change several rows. After a lost connection it reloads once
// on reconnecting, because notifications sent meanwhile are lost.
// Since step 3a.5 it also LISTENs on "work_order" (migration 015; payload =
// the line's id): output 2 asks "work orders" to read that line again, or
// every line after a reconnection.
const pg = global.get("pg");
const DEBOUNCE_MS = 300;
const BACKOFF_MS = [1000, 2000, 5000, 10000];
if (!pg) {
    node.error("the pg library is not available (see nodered/settings.js)");
    return null;
}

const old = context.get("state");
if (old) old.stop();
const st = { stopped: false, client: null, timer: null, debounce: null, attempts: 0, failures: 0, tables: new Set() };
st.stop = () => {
    st.stopped = true;
    clearTimeout(st.timer);
    clearTimeout(st.debounce);
    if (st.client) st.client.end().catch(() => { /* already closed */ });
};
context.set("state", st);

function schedule(table) {
    st.tables.add(table);
    clearTimeout(st.debounce);
    st.debounce = setTimeout(() => {
        const tables = [...st.tables].join(", ");
        st.tables.clear();
        node.send([{ trigger: "notify", changed: tables }, null]);
    }, DEBOUNCE_MS);
}

async function connect() {
    if (st.stopped) return;
    const client = new pg.Client({
        host: "timescaledb", port: 5432, database: "ofm",
        user: env.get("OFM_RUNTIME_DB_USER"), password: env.get("OFM_RUNTIME_DB_PASSWORD"),
        application_name: "ofm-runtime-listener", connectionTimeoutMillis: 5000, keepAlive: true
    });
    st.client = client;
    let lost = false;
    const onLost = e => {
        if (lost || st.stopped) return;
        lost = true;
        node.status({ fill: "red", shape: "ring", text: "not listening: " + ((e && e.message) || "connection closed") });
        client.end().catch(() => { /* already closed */ });
        st.timer = setTimeout(connect, BACKOFF_MS[Math.min(st.failures++, BACKOFF_MS.length - 1)]);
    };
    client.on("error", onLost);
    client.on("end", () => onLost());
    client.on("notification", n => {
        if (n.channel === "work_order") node.send([null, { topic: "work_order", lineId: Number(n.payload) }]);
        else schedule(n.payload || "?");
    });
    try {
        await client.connect();
        await client.query("LISTEN model_changed");
        await client.query("LISTEN work_order");
        st.failures = 0;
        node.status({ fill: "green", shape: "dot", text: "listening for model changes" });
        if (st.attempts++ > 0) {                             // changes may have been missed
            schedule("(reconnected)");
            node.send([null, { topic: "refresh" }]);
        }
    } catch (e) {
        st.attempts++;
        onLost(e);
    }
}
connect();
return null;

finalize:
// Close the listening connection when the flow is stopped or redeployed.
const st = context.get("state");
if (st) st.stop();
context.set("state", null);

func:
// Saved model copy (step 2.6, ADR-0001). Receives the error when the model
// cannot be loaded from the database (the "database not ready" catch node).
// If the runtime has no model yet - it has just started - it starts from the
// copy that "build model cache" saved after the last successful load, so
// values keep flowing to the UNS (and the historian's disk queue) while the
// database is down. Either way the database is retried every 10 s; once it
// answers, its model replaces the copy and only changed sources reconnect.
// Output 1: the saved rows, to "build model cache". Output 2: retry.
if (global.get("ofm_model")) return [null, msg];        // already running: keep the current model

const fs = global.get("fs"), path = global.get("path");
if (!fs || !path) {
    node.error("fs or path is not available (see nodered/settings.js)");
    return [null, msg];
}
const runtime = env.get("OFM_RUNTIME_NAME");
const file = path.join(env.get("OFM_MODEL_COPY_DIR") || "/data/model", runtime + ".json");
const reason = (msg.error && msg.error.message) || "database not reachable";

function refuse(why) {
    node.status({ fill: "red", shape: "ring", text: "no model yet: " + why });
    if (context.get("warned") !== why) {                    // once per reason, not every 10 s
        context.set("warned", why);
        node.warn("cannot load the model from the database (" + reason + ") and " + why +
                  ": no values until the database answers; retrying every 10 s");
    }
    return [null, msg];
}

let copy;
try {
    copy = JSON.parse(fs.readFileSync(file, "utf8"));
} catch (e) {
    return refuse(e.code === "ENOENT" ? "there is no saved model copy (" + file + ")"
                                      : "the saved model copy " + file + " cannot be read: " + e.message);
}
if (!copy || copy.format !== 1 || !Array.isArray(copy.rows) || !Number.isFinite(copy.savedAt)) {
    return refuse("the saved model copy " + file + " is not in the expected format");
}
if (copy.runtime !== runtime) {
    return refuse("the saved model copy " + file + " belongs to runtime " + copy.runtime);
}

const saved = new Date(copy.savedAt).toLocaleString("en-AU", { hour12: false });
node.warn("cannot load the model from the database (" + reason + "): starting from the copy saved " + saved +
          " (" + copy.rows.length + " properties); the database is retried every 10 s");
node.status({ fill: "yellow", shape: "dot", text: "started from the copy saved " + saved });
context.set("warned", null);
return [{ payload: copy.rows, trigger: "disk", savedAt: copy.savedAt }, msg];

// OPC UA acquisition (ADR-0017): one client per OPC UA source in the model.
// Input: the list of sources from "build model cache". Output 1: one message
// per value change. Output 2: one message per source connection change.
const opcua = global.get("opcua");
if (!opcua) {
    node.error("node-opcua is not available (see nodered/settings.js)");
    return null;
}

// A new model keeps the connections of unchanged sources; changed and
// removed sources are disconnected, new and changed ones (re)connected.
const wanted = {};
for (const src of (msg.payload || [])) if (src.protocol === "opcua") wanted[src.name] = src;
const old = context.get("clients") || {};
const clients = {};
for (const [name, s] of Object.entries(old)) {
    if (wanted[name] && wanted[name].signature === s.signature) { clients[name] = s; continue; }
    try { await s.client.disconnect(); } catch (e) { /* already closed */ }
}
context.set("clients", clients);

// OPC UA guarantees the namespace URI, not its number, so the model stores
// "nsu=<uri>;s=Name" and it is translated here to "ns=<number>;s=Name".
function translate(address, namespaces) {
    const m = /^nsu=([^;]+);(.+)$/.exec(address);
    if (!m) return address;
    const index = namespaces.indexOf(m[1]);
    if (index < 0) throw new Error("namespace " + m[1] + " is not on this server");
    return "ns=" + index + ";" + m[2];
}

function report(src, state, online, error) {
    if (state.online === online) return;          // only changes
    state.online = online;
    node.send([null, { payload: { source: src.name, online, error } }]);
    node.status(online ? { fill: "green", shape: "dot", text: src.name + " online" }
                       : { fill: "red", shape: "ring", text: src.name + " offline" });
}

async function start(src) {
    const settings = src.settings || {};
    const state = { client: null, online: null, signature: src.signature };
    clients[src.name] = state;
    const client = opcua.OPCUAClient.create({
        applicationName: "OFM " + env.get("OFM_RUNTIME_NAME"),
        endpointMustExist: false,
        securityMode: opcua.MessageSecurityMode[settings.securityMode || "None"],
        securityPolicy: opcua.SecurityPolicy[settings.securityPolicy || "None"],
        connectionStrategy: { initialDelay: 1000, maxDelay: 10000, maxRetry: -1 },   // retry forever
        keepSessionAlive: true
    });
    state.client = client;
    client.on("connection_lost", () => report(src, state, false, "connection lost"));
    client.on("connection_reestablished", () => report(src, state, true));
    client.on("backoff", () => report(src, state, false, "cannot reach " + src.endpoint));

    try {
        await client.connect(src.endpoint);
        const session = await client.createSession();
        const namespaces = await session.readNamespaceArray();
        const subscription = opcua.ClientSubscription.create(session, {
            requestedPublishingInterval: settings.publishingIntervalMs || 1000,
            requestedLifetimeCount: 60,
            requestedMaxKeepAliveCount: 20,
            publishingEnabled: true
        });
        for (const item of src.items) {
            // An address the server does not have is published as v null, q bad (step 2.4).
            const refuse = (why) => {
                node.warn(src.name + ": " + item.address + ": " + why + " - not read");
                node.send([{ payload: { source: src.name, address: item.address, value: null, status: "BadNodeIdUnknown",
                                        sourceTimestamp: null, receivedAt: Date.now() } }, null]);
            };
            let nodeId;
            try {
                nodeId = translate(item.address, namespaces);
            } catch (e) {
                refuse(e.message);
                continue;
            }
            const monitored = opcua.ClientMonitoredItem.create(subscription,
                { nodeId, attributeId: opcua.AttributeIds.Value },
                { samplingInterval: settings.samplingIntervalMs || 500, discardOldest: true, queueSize: 10 },
                opcua.TimestampsToReturn.Both);
            monitored.on("changed", (dv) => node.send([{
                payload: {
                    source: src.name,
                    address: item.address,                       // as stored in the model
                    value: dv.value ? dv.value.value : null,
                    status: dv.statusCode ? dv.statusCode.name : "Bad",
                    sourceTimestamp: dv.sourceTimestamp ? dv.sourceTimestamp.getTime() : null,
                    receivedAt: Date.now()
                }
            }, null]));
            monitored.on("err", (e) => refuse(String(e)));
        }
        report(src, state, true);
    } catch (e) {
        report(src, state, false, e.message);
        node.error(src.name + ": " + e.message);
    }
}

for (const src of Object.values(wanted)) {
    if (!clients[src.name]) start(src);                   // runs in the background
}
if (Object.keys(wanted).length === 0) node.status({});
return null;

finalize:
// Close every OPC UA connection when the flow is stopped or redeployed.
const clients = context.get("clients") || {};
for (const s of Object.values(clients)) {
    s.client.disconnect().catch(() => { /* already closed */ });   // "On Stop" code cannot wait
}
context.set("clients", {});

func:
// Polled acquisition (ADR-0018): Siemens S7 (S7 communication, PUT/GET) and
// Rockwell Logix controllers (EtherNet/IP, tag names). One connection per
// source in the model, read every pollIntervalMs. Read-only: never writes.
// Input: the list of sources from "build model cache". Output 1: one message
// per value that changed (and every value after each (re)connection);
// republishing unchanged values is done centrally by "heartbeat" (ADR-0007).
// Output 2: one message per source connection change.
// PLCs send no timestamps, so values are stamped by this gateway (ADR-0003).
const POLLED = ["s7", "ethernetip"];
const BACKOFF_MS = [1000, 2000, 5000, 10000];         // wait before reconnecting
const OPEN_TIMEOUT_MS = 5000;

// A new model keeps the connections of unchanged sources; changed and
// removed sources are closed, new and changed ones (re)connected.
const list = (msg.payload || []).filter(s => POLLED.includes(s.protocol));
const wanted = {};
for (const src of list) wanted[src.name] = src;
const old = context.get("sources") || {};
const sources = {};
for (const [name, s] of Object.entries(old)) {
    if (wanted[name] && wanted[name].signature === s.signature) sources[name] = s;
    else s.stop();
}
context.set("sources", sources);

function showStatus() {
    const all = Object.values(context.get("sources") || {});
    const off = all.filter(s => !s.online).map(s => s.name);
    node.status(all.length === 0 ? {}
        : off.length ? { fill: "red", shape: "ring", text: "offline: " + off.join(", ") }
        : { fill: "green", shape: "dot", text: all.length + " PLC(s) online" });
}

function report(st, online, error) {
    if (st.online === online) return;                  // only changes
    st.online = online;
    node.send([null, { payload: { source: st.name, online, error } }]);
    showStatus();
}

function hostPort(endpoint, defaultPort) {
    const m = /^\s*([^:\s]+)(?::(\d+))?\s*$/.exec(String(endpoint || ""));
    if (!m) throw new Error("endpoint must be an IP address or host name, optionally :port");
    return { host: m[1], port: m[2] ? Number(m[2]) : defaultPort };
}

function withTimeout(promise, ms, what) {
    let timer;
    return Promise.race([
        promise,
        new Promise((_, reject) => { timer = setTimeout(() => reject(new Error(what + ": no answer within " + ms / 1000 + " s")), ms); })
    ]).finally(() => clearTimeout(timer));
