// One driver per protocol: open a connection; probe one address (throws if
// it cannot be read); read a list of good addresses in as few requests as
// the protocol allows.
const drivers = {
    s7: async (src, settings) => {
        const lib = global.get("s7");
        if (!lib) throw new Error("S7 library is not available (see nodered/settings.js)");
        const { host, port } = hostPort(src.endpoint, 102);
        const ep = new lib.S7Endpoint({
            host, port,
            rack: Number.isInteger(settings.rack) ? settings.rack : 0,
            slot: Number.isInteger(settings.slot) ? settings.slot : 1,
            autoReconnect: 0                                // reconnecting is done below
        });
        ep.on("error", () => { /* reported by the next read */ });
        await withTimeout(ep.connect(), OPEN_TIMEOUT_MS, "connect to " + host);
        const probeGroup = new lib.S7ItemGroup(ep);
        let group = null, groupKey = null;
        return {
            probe: async address => {
                probeGroup.addItems(address);               // throws on a malformed address
                try { await probeGroup.readAllItems(); } finally { probeGroup.removeItems(address); }
            },
            read: async addresses => {
                const key = addresses.join("\n");
                if (key !== groupKey) {
                    group = new lib.S7ItemGroup(ep);
                    group.addItems(addresses);
                    groupKey = key;
                }
                const r = await group.readAllItems();
