        let tags = null, group = null, groupKey = null;
        return {
            probe: async address => {
                if (!lib.Tag.isValidTagname(address)) throw new Error("not a valid Logix tag name");
                await plc.readTag(new lib.Tag(address));
            },
            read: async addresses => {
                const key = addresses.join("\n");
                if (key !== groupKey) {
                    tags = addresses.map(a => new lib.Tag(a));
                    group = new lib.TagGroup();
                    tags.forEach(t => group.add(t));
                    groupKey = key;
                }
                if (tags.length === 1) await plc.readTag(tags[0]);
                else await plc.readTagGroup(group);
                return tags.map(t => t.value);
            },
            connected: () => !plc.destroyed && plc.established !== false,
            close: () => { try { plc.destroy(); } catch (e) { /* already closed */ } }
        };
    }
