        if (st.stopped) return;
        const last = {};                                // address -> last value sent, per connection
        try {
            st.conn = await drivers[src.protocol](src, settings);
            // Probe each address once, so one wrong address cannot stop the others.
            // An address the PLC refuses is published as v null, q bad (step 2.4).
            const good = [], refused = [];
            for (const item of src.items) {
                try {
                    await st.conn.probe(item.address);
                    good.push(item);
                } catch (e) {
