// --- database -------------------------------------------------------------------
const SQL_NUM = "INSERT INTO hist.measurement (ts, property_id, value, quality, ts_source) " +
    "SELECT to_timestamp(t / 1000.0), p, v, q, s FROM unnest($1::float8[], $2::int[], $3::float8[], $4::int[], $5::int[]) AS x(t, p, v, q, s) " +
    "ON CONFLICT (property_id, ts) DO NOTHING";
const SQL_TXT = SQL_NUM.replace("hist.measurement ", "hist.measurement_text ").replace("$3::float8[]", "$3::text[]");
const SQL_EVENT = "INSERT INTO hist.machine_state_event (ts, machine_id, state_id, cause) " +
    "SELECT to_timestamp(t / 1000.0), m, s, c FROM unnest($1::float8[], $2::int[], $3::int[], $4::text[]) AS x(t, m, s, c) " +
    "ON CONFLICT (machine_id, ts) DO NOTHING";
const SQL_COUNT = "INSERT INTO hist.production_count (ts, property_id, increment, last_value, resets) " +
    "SELECT to_timestamp(t / 1000.0), p, i, l, r FROM unnest($1::float8[], $2::int[], $3::float8[], $4::float8[], $5::int[]) AS x(t, p, i, l, r) " +
    "ON CONFLICT (property_id, ts) DO NOTHING";
const SQL_WO_EVENT = "INSERT INTO hist.work_order_event (ts, work_order_id, event_type, entered_by) " +
    "SELECT to_timestamp(t / 1000.0), w, e, b FROM unnest($1::float8[], $2::int[], $3::text[], $4::text[]) AS x(t, w, e, b) " +
    "ON CONFLICT (work_order_id, event_type) DO NOTHING";
const SQL_HEARTBEAT = "INSERT INTO hist.runtime_heartbeat (ts, runtime_name) " +
    "SELECT to_timestamp(t / 1000.0), r FROM unnest($1::float8[], $2::text[]) AS x(t, r) " +
    "ON CONFLICT (runtime_name, ts) DO NOTHING";

function columns(rows, fields) {
    return fields.map(i => rows.map(r => r[i]));
}
async function insert(rows) {
    const kind = r => typeof r[0] === "string" ? r[0] : null;                // "e" event, "h" heartbeat, "c" count, "w" work order event
    const isText = r => r[5] === "t" || typeof r[2] === "string";        // NULL values carry the "t" mark
    const values = rows.filter(r => kind(r) === null);
    const num = values.filter(r => !isText(r));
    const txt = values.filter(isText);
    const events = rows.filter(r => kind(r) === "e");
    const beats = rows.filter(r => kind(r) === "h");
    const counts = rows.filter(r => kind(r) === "c");
    const orders = rows.filter(r => kind(r) === "w");
    if (num.length) await pool().query(SQL_NUM, columns(num, [0, 1, 2, 3, 4]));
    if (txt.length) await pool().query(SQL_TXT, columns(txt, [0, 1, 2, 3, 4]));
    if (events.length) await pool().query(SQL_EVENT, columns(events, [1, 2, 3, 4]));
    if (beats.length) await pool().query(SQL_HEARTBEAT, columns(beats, [1, 2]));
    if (counts.length) await pool().query(SQL_COUNT, columns(counts, [1, 2, 3, 4, 5]));
