}

// --- flush, drain, status -----------------------------------------------------------
async function flush() {
    if (st.buf.length === 0) return;
    const rows = st.buf;
    st.buf = [];
    scan();
    if (st.files.length > 0 || Date.now() < st.nextTry) { enqueue(rows); return; }   // keep order behind the queue
    try {
        await write(rows);
        st.failures = 0;
    } catch (e) {
        enqueue(rows);
        st.nextTry = Date.now() + BACKOFF_MS[Math.min(st.failures++, BACKOFF_MS.length - 1)];
        node.status({ fill: "yellow", shape: "ring", text: "buffering: " + e.message });
