        const f = st.files[0];
        let rows;
        try {
            rows = JSON.parse(zlib.gunzipSync(fs.readFileSync(path.join(DIR, f.name))).toString());
        } catch (e) {
            node.warn("unreadable queue file " + f.name + " skipped: " + e.message);
            rows = [];
        }
        try {
            if (rows.length) await write(rows);
        } catch (e) {
            st.nextTry = Date.now() + BACKOFF_MS[Math.min(st.failures++, BACKOFF_MS.length - 1)];
