global.set("ofm_counters", counters);
const model = global.get("ofm_model");
const now = Date.now();
const rows = [], goods = [];
const minuteOf = ts => Math.floor(ts / MINUTE) * MINUTE;

function counterOf(id) {
    return counters[id] || (counters[id] = { last: null, buckets: {}, openFrom: minuteOf(now), held: [] });
}
function apply(id, c, v, ts) {
    if (c.last === null) { c.last = v; return; }        // first reading: the starting point
    let inc = v - c.last, reset = 0;
    if (v < c.last) {
        reset = 1;
        inc = Math.max(0, v);
        const p = model && model.byProperty[id];
        node.warn("counter " + (p ? p.topic : id) + " was reset: " + c.last + " -> " + v + "; counted " + inc + " since the reset");
    }
    c.last = v;
    if (inc === 0 && !reset) return;
    if (inc > 0 && (global.get("ofm_wo_watch") || {})[id]) goods.push({ topic: "good", propertyId: Number(id), ts });
    const minute = Math.max(minuteOf(ts), c.openFrom, minuteOf(Date.now() - GRACE_MS));   // the oldest minute still open
    const b = c.buckets[minute] || (c.buckets[minute] = { inc: 0, resets: 0, lastValue: v });
    b.inc += inc;
    b.resets += reset;
    b.lastValue = v;
}

if (msg.topic === "count") {
    const c = counterOf(msg.propertyId);
    if (!global.get("ofm_counts_ready")) {
        if (c.held.length >= HOLD_MAX) c.held.pop();       // keep the first and the newest
        c.held.push([msg.v, msg.ts]);
        return null;
    }
    apply(msg.propertyId, c, msg.v, msg.ts);
    return goods.length ? [null, goods] : null;
}

if (msg.topic === "ready") {
    const base = msg.counters || {};
    for (const [id, last] of Object.entries(base)) {
        const c = counterOf(id);
        if (c.last === null) c.last = Number(last);
    }
    global.set("ofm_counts_ready", Date.now());
    for (const [id, c] of Object.entries(counters)) {
        const held = c.held || [];
        c.held = [];
        c.openFrom = Math.max(c.openFrom, minuteOf(now));
        for (const [v, ts] of held) apply(id, c, v, ts);
    }
}

// Tick (and after "ready"): write every minute that is over.
for (const [id, c] of Object.entries(counters)) {
    // No longer a counter (role, mapping or property removed): counting stops
    // at once and its unwritten minutes are dropped, so nothing is written
    // for a property that may be about to be deleted (migrate demo-remove).
    const p = model && model.byProperty[id];
    if (model && !(p && p.counter)) { delete counters[id]; continue; }
    for (const key of Object.keys(c.buckets)) {
        const minute = Number(key);
        if (now < minute + MINUTE + GRACE_MS) continue;
        const b = c.buckets[key];
        rows.push({ params: ["c", minute, Number(id), b.inc, b.lastValue, b.resets] });
        delete c.buckets[key];
        c.openFrom = Math.max(c.openFrom, minute + MINUTE);
    }
}
if (rows.length) {
    const units = rows.reduce((s, r) => s + r.params[3], 0);
    node.status({ fill: "green", shape: "dot", text: Object.keys(counters).length + " counters; last write " +
                  rows.length + " row(s), " + Math.round(units) + " units" });
}
return rows.length || goods.length ? [rows.length ? rows : null, goods.length ? goods : null] : null;

// Work orders (ADR-0010, step 3a.5). Publishes each line's active order,
// retained, on {enterprise}/{site}/{area}/{line}/workorder
// (schemas/workorder.schema.json), and closes a changeover at the first good
// unit of the new order.
// Inputs:
// - "work_order" {lineId} from the listener: an event was recorded on that
//   line (channel work_order, migration 015) -> that line is read again;
// - "refresh": after start-up reconciliation, after every model load, and
//   after the listener reconnects -> every line is read again; a line that
//   no longer has orders, or was renamed, has its old topic cleared;
// - "good" {propertyId, ts} from "counts": a counter in global ofm_wo_watch
//   (count_good of the output machine of a line in changeover) went up.
//   If its own time is GUARD_MS or more after the start (earlier units are
//   the previous order's, still on their way), the changeover ends then:
//   a changeover_end event, entered_by "ofm", through the historian writer;
//   a changeover_end already recorded (an operator's) is kept (ADR-0010);
// - the 1-second tick: after a failed read, every line is read again
//   RETRY_MS later.
// Output 1: UNS. Output 2: historian rows ["w", ts, workOrderId, "changeover_end", "ofm"].
const GUARD_MS = 10000;
const RETRY_MS = 10000;
const pg = global.get("pg");
const lines = global.get("ofm_work_orders") || {};
global.set("ofm_work_orders", lines);

function payloadOf(r) {
    const ts = Number(r.ts_ms);
    if (!r.active) return { active: false, ts };
    return {
        active: true, ts,
        workOrderId: r.work_order_id, woNumber: r.wo_number, productId: r.material_id, sku: r.sku,
        plannedQty: r.planned_qty, ratePerHour: Number(r.rate_per_hour),
        startedTs: Number(r.started_ms), changeover: r.changeover
    };
}
function watch() {
    const w = {};
    for (const l of Object.values(lines)) {
        if (l.payload.active && l.payload.changeover && l.goodPropertyId) w[l.goodPropertyId] = l.lineId;
    }
    global.set("ofm_wo_watch", w);
}
function publish(l) {
    return { topic: l.topic + "/workorder", payload: l.payload, retain: true, qos: 1 };
}

if (msg.topic === "good") {
    const lineId = (global.get("ofm_wo_watch") || {})[msg.propertyId];
    const l = lineId && lines[lineId];
    if (!l || !l.payload.active || !l.payload.changeover || msg.ts < l.payload.startedTs + GUARD_MS) return null;
    const ts = Math.round(msg.ts);
    l.payload = Object.assign({}, l.payload, { changeover: false, ts });
    l.closedLocally = l.payload.workOrderId;
    watch();
    node.log("work order " + l.payload.woNumber + ": changeover ended at the first good unit");
    return [publish(l), { params: ["w", ts, l.payload.workOrderId, "changeover_end", "ofm"] }];
}

let topic = msg.topic;
if (topic !== "work_order" && topic !== "refresh") {                  // the tick
    const retryAt = context.get("retryAt");
    if (!retryAt || Date.now() < retryAt) return null;
    topic = "refresh";
}
context.set("retryAt", null);
if (!pg) { node.error("the pg library is not available (see nodered/settings.js)"); return null; }
const pool = context.get("pool") || new pg.Pool({
    host: "timescaledb", port: 5432, database: "ofm",
    user: env.get("OFM_RUNTIME_DB_USER"), password: env.get("OFM_RUNTIME_DB_PASSWORD"),
    application_name: "ofm-runtime-workorders", max: 1, connectionTimeoutMillis: 5000
});
if (!context.get("pool")) { pool.on("error", () => { /* reconnects on the next query */ }); context.set("pool", pool); }

const one = topic === "work_order" && Number.isFinite(Number(msg.lineId));
let rows;
try {
    rows = (await pool.query(
        "SELECT line_id, line_topic, active, extract(epoch FROM ts) * 1000 AS ts_ms, work_order_id, wo_number, material_id, sku, " +
        "planned_qty, extract(epoch FROM started_at) * 1000 AS started_ms, changeover, rate_per_hour, good_property_id " +
        "FROM hist.vw_line_work_order" + (one ? " WHERE line_id = $1" : ""), one ? [Number(msg.lineId)] : [])).rows;
} catch (e) {
    node.status({ fill: "red", shape: "ring", text: "cannot read work orders: " + e.message });
    context.set("retryAt", Date.now() + RETRY_MS);
    return null;
}

const out = [];
const seen = new Set();
for (const r of rows) {
    seen.add(String(r.line_id));
    const payload = payloadOf(r);
    payload.ts = Math.round(payload.ts);
    if (payload.startedTs !== undefined) payload.startedTs = Math.round(payload.startedTs);
    const old = lines[r.line_id];
    // The runtime closed this changeover a moment ago; the database may not have it yet.
    if (old && old.closedLocally === payload.workOrderId && payload.active && payload.changeover) {
        payload.changeover = false;
        payload.ts = old.payload.ts;
    }
    if (old && old.topic !== r.line_topic) out.push({ topic: old.topic + "/workorder", payload: "", retain: true, qos: 1 });
    const l = { lineId: r.line_id, topic: r.line_topic, goodPropertyId: r.good_property_id, payload,
                closedLocally: old && old.closedLocally === payload.workOrderId ? old.closedLocally : null };
    if (!old || old.topic !== l.topic || JSON.stringify(old.payload) !== JSON.stringify(payload)) out.push(publish(l));
    lines[r.line_id] = l;
}
if (!one) {
    for (const id of Object.keys(lines)) {
        if (seen.has(id)) continue;
        out.push({ topic: lines[id].topic + "/workorder", payload: "", retain: true, qos: 1 });
        delete lines[id];
    }
}
watch();
const active = Object.values(lines).filter(l => l.payload.active);
node.status({ fill: "green", shape: "dot", text: active.length + " active order(s)" +
              (active.length === 1 ? ": " + active[0].payload.woNumber + " " + active[0].payload.sku + (active[0].payload.changeover ? ", changeover" : "") : "") });
return [out.length ? out : null, null];
